import { Activity as ActivityIcon, ArrowLeft, BarChart3, CalendarDays, ChevronDown, CircleGauge, CloudDownload, Dumbbell, Footprints, Heart, Import, LayoutList, LoaderCircle, MapPin, MessageSquare, MoreHorizontal, Mountain, NotebookPen, Plus, Search, Send, Settings as SettingsIcon, Sparkles, Star, Tag, Timer, Trash2, TrendingUp, Upload, WandSparkles, X } from 'lucide-react'
