type View='log'|'progress'|'cycles'|'planner'|'profile'|'settings'
type GarminPrompt={kind:'password'|'mfa';value:string}
const ACTIVITY_TYPES=[
  ['running','Running'],['cycling','Cycling'],['hiking','Hiking'],['walking','Walking'],
  ['cross_country_skiing','Cross-country skiing'],['alpine_skiing','Alpine skiing'],['backcountry_skiing','Backcountry skiing'],
  ['lap_swimming','Pool swimming'],['open_water_swimming','Open-water swimming'],['swimming','Swimming'],
  ['rowing','Rowing'],['indoor_rowing','Indoor rowing'],['strength_training','Strength training'],
  ['cross_training','Cross training'],['elliptical','Elliptical'],['yoga','Yoga'],['other','Other'],
] as const
const activityTypeLabel=(sport:string)=>ACTIVITY_TYPES.find(([value])=>value===sport)?.[1]||sport.replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase())
const browserPreviewApi:Window['runningLog']={invoke:async<T,>(channel:any)=>{if(channel==='dashboard:get')return{activities:[],cycles:[],settings:{}} as T;if(channel==='athlete-profile:get')return{generatedAt:new Date().toISOString(),runningActivities:0,intervalWorkouts:0,reps:0,assessedReps:0,anchors:[{id:'mile',label:'Mile pace',targetPaceSecPerM:.18,reps:0,workouts:0},{id:'3k',label:'3K pace',targetPaceSecPerM:.2,reps:0,workouts:0},{id:'5k',label:'5K pace',targetPaceSecPerM:.21,reps:0,workouts:0},{id:'8k',label:'8K pace',targetPaceSecPerM:.22,reps:0,workouts:0},{id:'threshold',label:'Sub-threshold',targetPaceSecPerM:.23,reps:0,workouts:0},{id:'easy',label:'Easy',reps:0,workouts:0},{id:'recovery',label:'Recovery',reps:0,workouts:0}],selectedAnchorId:'3k',selectedExposureBand:'all',windowWeeks:6,comparison:{anchorId:'3k',anchorLabel:'3K pace',exposureBand:'all',windowWeeks:6,latestReps:0,baselineReps:0,baselineWorkouts:0,latestMechanics:{},baselineMechanics:{},changes:[],changeState:'insufficient',confidence:'none',summary:'No reps match this intensity and duration selection.'},trend:[],lifestyle:{collection:'not_collected',influence:'none',explanation:'Lifestyle data is not currently collected or used.'},limitations:['Import running activities to begin learning.']} as T;if(channel==='recovery:get')return null as T;if(channel==='settings:has-api-key')return false as T;if(channel==='manual:create')return'manual:preview' as T;return[] as T},pathsForFiles:()=>[],onProgress:()=>()=>{}}
const api=window.runningLog||browserPreviewApi

export default function App(){
  const [view,setView]=useState<View>('log'),[viewHistory,setViewHistory]=useState<View[]>([]),[visitedViews,setVisitedViews]=useState<Set<View>>(()=>new Set(['log'])),[data,setData]=useState<DashboardData>({activities:[],activityCount:0,cycles:[],settings:{}}),[selected,setSelected]=useState<string>(),[activity,setActivity]=useState<Activity>(),[filters,setFilters]=useState({search:'',type:'',surface:'',cycle:''}),[listLimit,setListLimit]=useState(200),[busy,setBusy]=useState(''),[toast,setToast]=useState(''),[drag,setDrag]=useState(false),[garminPrompt,setGarminPrompt]=useState<GarminPrompt>(),[manualOpen,setManualOpen]=useState(false),scrollPositions=useRef<Partial<Record<View,number>>>({})
  const refresh=useCallback(async()=>{const next=await api.invoke<DashboardData>('dashboard:get',{...filters,limit:listLimit});setData(next);setSelected(s=>s||next.activities[0]?.id)},[filters,listLimit])
  useEffect(()=>{refresh()},[refresh]);useEffect(()=>{if(selected)api.invoke<Activity>('activity:get',selected).then(setActivity);else setActivity(undefined)},[selected])
  useEffect(()=>api.onProgress(e=>{if(e.type==='mfa_required'){setBusy('Waiting for Garmin verification…');setGarminPrompt({kind:'mfa',value:''})}else if(e.type==='progress')setBusy(e.message||'Syncing Garmin…');else if(e.type==='done'){setBusy('');setToast(`${e.count??0} activities synced${e.skipped?` · ${e.skipped} unavailable`:''}`);refresh()}else if(e.type==='error'){setBusy('');setToast(e.message||'Something went wrong')}else if(e.type==='analysis'){if(e.status==='started')setBusy(e.message||'OpenRouter is analyzing this workout…');else if(e.status==='done'){setBusy('');if(e.message)setToast(e.message);refresh();if(selected)api.invoke<Activity>('activity:get',selected).then(setActivity)}else if(e.status==='error'){setBusy('');setToast(e.message||'AI analysis failed')}}}),[refresh,selected])
  useEffect(()=>{const stop=(e:DragEvent)=>{e.preventDefault();e.stopPropagation()};const enter=(e:DragEvent)=>{stop(e);setDrag(true)},leave=(e:DragEvent)=>{stop(e);if(!e.relatedTarget)setDrag(false)},drop=async(e:DragEvent)=>{stop(e);setDrag(false);const files=[...(e.dataTransfer?.files||[])].filter(f=>f.name.toLowerCase().endsWith('.fit'));if(files.length){setBusy(`Importing ${files.length} file${files.length===1?'':'s'}…`);const r=await api.invoke<any[]>('import:paths',api.pathsForFiles(files));setBusy('');setToast(`${r.filter(x=>x.inserted).length} imported · ${r.filter(x=>!x.inserted).length} skipped`);refresh()}};window.addEventListener('dragover',enter);window.addEventListener('dragleave',leave);window.addEventListener('drop',drop);return()=>{window.removeEventListener('dragover',enter);window.removeEventListener('dragleave',leave);window.removeEventListener('drop',drop)}},[refresh])
  async function importFiles(){setBusy('Choosing FIT files…');const r=await api.invoke<any[]>('dialog:import');setBusy('');if(r.length){setToast(`${r.filter(x=>x.inserted).length} activities imported`);refresh()}}
  function sync(){setGarminPrompt({kind:'password',value:''})}
  async function submitGarmin(){if(!garminPrompt)return;const {kind,value}=garminPrompt;setGarminPrompt(undefined);try{if(kind==='mfa'){setBusy('Verifying with Garmin…');await api.invoke('garmin:mfa',value)}else{setBusy('Starting Garmin sync…');await api.invoke('garmin:sync',value)}}catch(e){setBusy('');setToast(e instanceof Error?e.message:String(e))}}
  const showView=(next:View,remember=true)=>{if(next===view)return;scrollPositions.current[view]=window.scrollY;if(remember)setViewHistory(history=>[...history,view]);setVisitedViews(visited=>visited.has(next)?visited:new Set(visited).add(next));setView(next);requestAnimationFrame(()=>window.scrollTo({top:scrollPositions.current[next]||0,behavior:'auto'}))}
  const goBack=()=>{const previous=viewHistory.at(-1);if(!previous)return;scrollPositions.current[view]=window.scrollY;setViewHistory(history=>history.slice(0,-1));setView(previous);requestAnimationFrame(()=>window.scrollTo({top:scrollPositions.current[previous]||0,behavior:'auto'}))}
  return <div className="app">
    <header><div className="brand"><button className="back-button" disabled={!viewHistory.length} onClick={goBack} aria-label="Back" title="Back"><ArrowLeft size={17}/></button><span className="brand-mark"><ActivityIcon size={18}/></span><span>Running Log</span></div><nav>{([['log',LayoutList,'Log'],['progress',TrendingUp,'Progress'],['cycles',CalendarDays,'Cycles'],['planner',WandSparkles,'Planner'],['profile',CircleGauge,'Athlete'],['settings',SettingsIcon,'Settings']] as const).map(([v,I,l])=><button className={view===v?'active':''} onClick={()=>showView(v)} key={v}><I size={16}/>{l}</button>)}</nav><div className="header-actions"><button className="ghost" onClick={()=>setManualOpen(true)}><Plus size={16}/>Add workout</button><button className="ghost" onClick={importFiles}><Import size={16}/>Import FIT</button><button className="primary" onClick={sync}><CloudDownload size={16}/>Sync Garmin</button></div></header>
    <div className="view-pane" hidden={view!=='log'}><LogView data={data} filters={filters} setFilters={next=>{setListLimit(200);setFilters(next)}} loadMore={()=>setListLimit(limit=>limit+200)} selected={selected} select={setSelected} activity={activity} refresh={async()=>{await refresh();if(selected)setActivity(await api.invoke('activity:get',selected))}} busy={(s)=>setBusy(s)} toast={setToast}/></div>
    {visitedViews.has('progress')&&<div className="view-pane" hidden={view!=='progress'}><ProgressView data={data} open={id=>{setSelected(id);showView('log')}}/></div>}
    {visitedViews.has('cycles')&&<div className="view-pane" hidden={view!=='cycles'}><CyclesView cycles={data.cycles} units={data.settings.units} openRun={id=>{setSelected(id);showView('log')}} refresh={refresh}/></div>}
    {visitedViews.has('planner')&&<div className="view-pane" hidden={view!=='planner'}><PlannerView cycles={data.cycles} stored={data.settings.fitness_profile} historyStored={data.settings.fitness_profile_history} refresh={refresh} toast={setToast}/></div>}
    {visitedViews.has('profile')&&<div className="view-pane" hidden={view!=='profile'}><AthleteProfileView units={data.settings.units} open={id=>{setSelected(id);showView('log')}}/></div>}
    {visitedViews.has('settings')&&<div className="view-pane" hidden={view!=='settings'}><SettingsView settings={data.settings} refresh={refresh} toast={setToast}/></div>}
    {drag&&<div className="drop-zone"><div><Upload size={38}/><strong>Drop FIT files to import</strong><span>Original watch data stays on this Mac</span></div></div>}
    {garminPrompt&&<div className="modal-backdrop"><form className="secret-modal" onSubmit={e=>{e.preventDefault();submitGarmin()}}><span className="modal-icon"><CloudDownload size={20}/></span><h2>{garminPrompt.kind==='mfa'?'Garmin verification':'Connect to Garmin'}</h2><p>{garminPrompt.kind==='mfa'?'Enter the verification code Garmin sent you.':'Enter your password for the first sign-in. Leave it blank if this app has connected before. Your password is never stored.'}</p><label>{garminPrompt.kind==='mfa'?'Verification code':'Garmin password'}<input autoFocus type={garminPrompt.kind==='mfa'?'text':'password'} autoComplete="off" value={garminPrompt.value} onChange={e=>setGarminPrompt({...garminPrompt,value:e.target.value})}/></label><div className="modal-actions"><button type="button" className="ghost" onClick={()=>setGarminPrompt(undefined)}>Cancel</button><button className="primary" type="submit" disabled={garminPrompt.kind==='mfa'&&!garminPrompt.value.trim()}>{garminPrompt.kind==='mfa'?'Verify':'Continue'}</button></div></form></div>}
    {manualOpen&&<ManualWorkoutModal close={()=>setManualOpen(false)} created={async id=>{setManualOpen(false);showView('log');await refresh();setSelected(id);setToast('Manual workout added')}}/>}
    {busy&&<div className="busy"><LoaderCircle className="spin" size={17}/>{busy}</div>}{toast&&<div className="toast" onClick={()=>setToast('')}>{toast}<X size={14}/></div>}
  </div>
}

function LogView({data,filters,setFilters,loadMore,selected,select,activity,refresh,busy,toast}:{data:DashboardData;filters:any;setFilters:(x:any)=>void;loadMore:()=>void;selected?:string;select:(x:string)=>void;activity?:Activity;refresh:()=>Promise<void>;busy:(x:string)=>void;toast:(x:string)=>void}){
  const total=data.activityCount??data.activities.length
  return <main className="log-layout"><aside className="run-list"><div className="list-head"><div><span className="eyebrow">TRAINING LOG</span><h1>{total} workouts</h1></div><button className="icon-btn"><MoreHorizontal size={18}/></button></div><div className="search"><Search size={15}/><input placeholder="Search workouts, exercises, notes…" value={filters.search} onChange={e=>setFilters({...filters,search:e.target.value})}/></div><div className="filters"><select value={filters.type} onChange={e=>setFilters({...filters,type:e.target.value})}><option value="">All workouts</option>{WORKOUT_TYPES.map(x=><option key={x}>{x}</option>)}</select><select value={filters.cycle} onChange={e=>setFilters({...filters,cycle:e.target.value})}><option value="">All cycles</option>{data.cycles.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></div><div className="runs">{data.activities.map(a=><button className={`run-row ${selected===a.id?'selected':''}`} onClick={()=>select(a.id)} key={a.id}><div className="date-tile"><b>{shortDate(a.local_date).split(' ')[1]}</b><span>{shortDate(a.local_date).split(' ')[0]}</span></div><div className="run-copy"><div className="run-title"><strong>{a.name}</strong>{a.has_journal?<MessageSquare size={13}/>:null}</div><div className="run-meta">{a.distance_m>0?<><span>{distance(a.distance_m,data.settings.units)}</span><i>·</i><span>{pace(a.duration_s/a.distance_m,data.settings.units)}</span></>:<span>{duration(a.duration_s)}</span>}{a.rep_count?<><i>·</i><span>{a.rep_count} reps</span></>:null}</div><div className="badge-row"><TypeBadge type={a.workout_type} source={a.type_source}/><span className="surface">{a.sport.replaceAll('_',' ')}</span></div></div></button>)}{data.activities.length<total&&<button className="load-more" onClick={loadMore}>Show 200 more <span>{total-data.activities.length} remaining</span></button>}{!data.activities.length&&<EmptyLog/>}</div></aside><section className="detail">{activity?<ActivityDetail key={activity.id} activity={activity} units={data.settings.units} refresh={refresh} busy={busy} toast={toast}/>:<div className="blank"><Footprints size={34}/><h2>Your training lives here</h2><p>Import a FIT file, sync Garmin, or add a manual workout.</p></div>}</section></main>
}
function EmptyLog(){return <div className="empty-list"><Footprints size={26}/><strong>No workouts yet</strong><span>Drop a .fit file anywhere</span></div>}
function TypeBadge({type,source}:{type:string;source:string}){return <span className={`type-badge ${type.toLowerCase().replace(/ /g,'-')}`}>{type}<small>{source==='user'?'YOU':source.toUpperCase()}</small></span>}

function ActivityDetail({activity:a,units,refresh,busy,toast}:{activity:Activity;units:string;refresh:()=>Promise<void>;busy:(s:string)=>void;toast:(s:string)=>void}){
  const [similar,setSimilar]=useState<any[]>([]),[note,setNote]=useState(''),[editing,setEditing]=useState(false)
  const isManual=a.source==='manual',isStrength=a.sport==='strength_training',isSwimming=a.sport.includes('swim'),isRunning=a.sport.includes('run'),swimSession=(a.raw_fit_json as any)?.sessions?.[0]||a.raw_summary||{},swimYards=swimSession.pool_length_unit==='statute',swimDistanceValue=swimYards?a.distance_m/0.9144:a.distance_m,swimDistanceUnit=swimYards?'yd':'m'
  useEffect(()=>{if(isManual)setSimilar([]);else api.invoke<any[]>('similar:get',a.id).then(setSimilar)},[a.id,isManual])
  const save=async(changes:any)=>{await api.invoke('activity:update',a.id,changes);await refresh()}
  const analyze=async()=>{busy('OpenRouter is analyzing this workout…');try{const r=await api.invoke<any>('ai:analyze',a.id);if(r.skipped)toast('Add an OpenRouter API key in Settings first');await refresh()}catch(e){busy('');toast(`Analysis failed: ${String(e)}`)}}
  const addNote=async()=>{if(!note.trim())return;await api.invoke('journal:add',{activity_id:a.id,entry_date:new Date().toISOString().slice(0,10),body:note.trim()});setNote('');await refresh()}
  return <div className="detail-inner"><div className="detail-head"><div><span className="eyebrow">{longDate(a.local_date)}</span><input className="title-input" defaultValue={a.name} onBlur={e=>{const name=e.target.value.trim();if(name&&(name!==a.name||a.name_source!=='user'))save({name})}}/><div className="byline">{isManual?<Dumbbell size={14}/>:<MapPin size={14}/>} {a.sport.replaceAll('_',' ')} · {isManual?'Manual entry':`${a.surface} · ${a.source==='demo'?'Demo data':a.source==='garmin'?'Garmin Connect':'FIT import'}`}</div></div><div className="detail-actions">{!isManual&&<button className="secondary" onClick={analyze}><Sparkles size={16}/>{a.ai_at?'Re-analyze':'Analyze with AI'}</button>}{a.laps?.some(l=>l.is_rep)&&<select className="type-select" title="Interval category" value={a.interval_category||'mixed'} onChange={e=>save({interval_category:e.target.value})}>{INTERVAL_CATEGORIES.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select>}<select className="type-select" value={a.workout_type} onChange={e=>save({workout_type:e.target.value})}>{WORKOUT_TYPES.map(t=><option key={t}>{t}</option>)}</select></div></div>
    {isManual?<div className="stat-strip manual-stats"><Stat label="Duration" value={duration(a.duration_s)}/><Stat label="Exercises" value={String(a.exercises?.length||0)}/><Stat label="Total sets" value={String((a.exercises||[]).reduce((n,e)=>n+(e.sets||0),0))}/><Stat label="Legs" value={a.legs_feel?`${a.legs_feel}/5`:'—'}/></div>:isSwimming?<div className="stat-strip"><Stat label="Distance" value={a.distance_m?`${Math.round(swimDistanceValue)} ${swimDistanceUnit}`:'—'}/><Stat label="Time" value={duration(a.duration_s)}/><Stat label={`Pace /100 ${swimDistanceUnit}`} value={a.distance_m?duration(a.duration_s/swimDistanceValue*100):'—'}/><Stat label="Avg HR" value={a.avg_hr?`${Math.round(a.avg_hr)} bpm`:'—'}/><Stat label="Active lengths" value={swimSession.num_active_lengths?String(swimSession.num_active_lengths):'—'}/><Stat label="Stroke rate" value={a.avg_cadence?`${Math.round(a.avg_cadence)} spm`:'—'}/></div>:<div className="stat-strip"><Stat label="Distance" value={a.distance_m?distance(a.distance_m,units):'—'}/><Stat label="Time" value={duration(a.duration_s)}/><Stat label="Avg pace" value={a.distance_m?pace(a.duration_s/a.distance_m,units):'—'}/><Stat label="Avg HR" value={a.avg_hr?`${Math.round(a.avg_hr)} bpm`:'—'}/><Stat label="Elevation" value={a.elev_gain_m?`${Math.round(a.elev_gain_m*(units==='mi'?3.28084:1))} ${units==='mi'?'ft':'m'}`:'—'}/><Stat label="Cadence" value={a.avg_cadence?`${Math.round(a.avg_cadence)} ${a.sport.includes('run')?'spm':'rpm'}`:'—'}/></div>}
    <AthleteLog activity={a} note={note} setNote={setNote} addNote={addNote} save={save}/>
    {isRunning&&['Easy','Recovery'].includes(a.workout_type)&&<RecoveryMechanics activity={a}/>} 
    {isStrength&&<StrengthExerciseEditor activity={a} refresh={refresh} toast={toast}/>} 
    {a.ai_summary&&<section className="analysis-card"><div className="analysis-icon"><Sparkles size={17}/></div><div><div className="card-label">AI TRAINING NOTE <span>· {a.ai_model||'auto analysis'}</span></div><p>{a.ai_summary}</p></div></section>}
    <WorkoutChat activity={a} toast={toast}/>
    {!isManual&&<><RouteMap activity={a}/><MetricChart activity={a} units={units}/>{isRunning&&<FormBreakdown activity={a} units={units}/>} {isSwimming&&<SwimData activity={a}/>}<GarminData activity={a}/>{!isSwimming&&<section className="panel"><div className="section-title"><div><span className="eyebrow">SPLITS</span><h2>Laps <em>{a.laps?.filter(l=>l.is_rep).length||0} reps flagged</em></h2></div><span className="hint">Click checkboxes to correct reps</span></div><LapTable laps={a.laps||[]} units={units} onToggle={async(l,v)=>{await api.invoke('lap:toggle',a.id,l.idx,v);await refresh()}}/></section>}</>}
    {isManual?<Journal entries={a.journal||[]} note="" setNote={()=>{}} add={()=>{}} refresh={refresh} showComposer={false}/>:<div className="two-col"><Metadata a={a} save={save}/><Journal entries={a.journal||[]} note="" setNote={()=>{}} add={()=>{}} refresh={refresh} showComposer={false}/></div>}
    {!isManual&&<section className="panel similar"><div className="section-title"><div><span className="eyebrow">HISTORY</span><h2>Similar workouts</h2></div></div>{similar.length?<div className="similar-grid">{similar.map(x=><div key={x.id}><span>{shortDate(x.local_date)}</span><strong>{x.name}</strong><small>{x.rep_count?`${x.rep_count} reps · `:''}{pace(x.sec_per_m,units)}</small></div>)}</div>:<p className="muted">More comparable workouts will appear here as your log grows.</p>}</section>}
  </div>
}
function WorkoutChat({activity,toast}:{activity:Activity;toast:(message:string)=>void}){
  const [messages,setMessages]=useState<WorkoutChatMessage[]>([]),[question,setQuestion]=useState(''),[loading,setLoading]=useState(true),[sending,setSending]=useState(false)
  const load=useCallback(async()=>{setLoading(true);try{setMessages(await api.invoke<WorkoutChatMessage[]>('workout-chat:list',activity.id))}finally{setLoading(false)}},[activity.id])
  useEffect(()=>{void load()},[load])
  const ask=async(text=question)=>{const value=text.trim();if(!value||sending)return;setQuestion('');setSending(true);setMessages(current=>[...current,{id:-Date.now(),activity_id:activity.id,role:'user',body:value,created_at:new Date().toISOString()}]);try{const result=await api.invoke<{message?:WorkoutChatMessage;skipped?:boolean}>('workout-chat:send',activity.id,value);if(result.skipped){toast('Add an OpenRouter API key in Settings first');setMessages(current=>current.filter(message=>message.id>=0))}else await load()}catch(error){setMessages(current=>current.filter(message=>message.id>=0));setQuestion(value);toast(`Chat failed: ${error instanceof Error?error.message:String(error)}`)}finally{setSending(false)}}
  const prompts=activity.laps?.some(lap=>lap.is_rep)?['How did my mechanics change across the reps?','Compare this with similar workouts.','Where did form drift begin, and what supports that?']:['How mechanically fresh did I look?','Compare this with similar runs.','What should I remember from this workout?']
  return <section className="panel workout-chat"><div className="section-title"><div><span className="eyebrow">ASK ABOUT THIS WORKOUT</span><h2>Training conversation</h2></div>{messages.length>0&&<button className="ghost chat-clear" onClick={async()=>{if(!confirm('Clear this workout conversation?'))return;await api.invoke('workout-chat:clear',activity.id);setMessages([])}}><Trash2 size={13}/>Clear</button>}</div><p className="chat-context">Uses this workout’s laps, mechanics, notes, cycle context, and up to eight comparable sessions. It will call out missing or non-comparable data.</p>{loading?<div className="chat-loading"><LoaderCircle className="spin" size={16}/>Loading conversation…</div>:messages.length?<div className="chat-thread">{messages.map(message=><div className={`chat-message ${message.role}`} key={message.id}><span>{message.role==='user'?'You':'AI assistant'}</span><p>{message.body}</p>{message.role==='assistant'&&message.model&&<small>{message.model}</small>}</div>)}{sending&&<div className="chat-message assistant thinking"><span>AI assistant</span><p><LoaderCircle className="spin" size={14}/> Looking through the workout and comparisons…</p></div>}</div>:<div className="chat-starters">{prompts.map(prompt=><button type="button" key={prompt} onClick={()=>void ask(prompt)}>{prompt}</button>)}</div>}<form className="chat-compose" onSubmit={event=>{event.preventDefault();void ask()}}><textarea value={question} onChange={event=>setQuestion(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();void ask()}}} placeholder="Ask about pacing, mechanics, form drift, or similar workouts…" maxLength={3000}/><button className="primary" disabled={sending||!question.trim()} aria-label="Send question">{sending?<LoaderCircle className="spin" size={16}/>:<Send size={16}/>}Ask</button></form><small className="chat-hint">Enter sends · Shift + Enter adds a new line</small></section>
}
const blankExercise=(idx:number):StrengthExercise=>({idx,exercise:'',tracking_type:'reps',sets:3,reps:10,weight_unit:'lb',band_color:'',notes:''})
