function loadFitnessProfile(stored?:string):FitnessProfile{try{const p=JSON.parse(stored||'');if(Array.isArray(p.prs)&&Array.isArray(p.current)&&Array.isArray(p.goals))return p}catch{}return structuredClone(DEFAULT_FITNESS_PROFILE)}
